import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('registers a tool requiring a location string, calls execute with {}, and asserts the returned result names location as required and the executors call count is 0', async () => {
    const registry = new ToolRegistry();
    let calls = 0;
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        calls++;
        return 'ok';
      }
    );

    const response = await registry.execute('weather', {});

    expect(response.result).toContain('location');
    expect(response.result).toContain('required');
    expect(calls).toBe(0);
  });

  it('asserts valid input with an unlisted extra property is passed through to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    let capturedInput: Record<string, unknown> | undefined;
    registry.register(
      {
        name: 'test_tool',
        description: 'A test tool',
        inputSchema: {
          type: 'object',
          properties: {foo: {type: 'string'}},
        },
      },
      async input => {
        capturedInput = input;
        return 'ok';
      }
    );

    await registry.execute('test_tool', {foo: 'bar', extra: 123});

    expect(capturedInput).toEqual({foo: 'bar', extra: 123});
  });

  it('asserts a wrong-typed field is rejected with a message naming the field path and the expected type, and that the message does not contain the offending value', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'test_tool',
        description: 'A test tool',
        inputSchema: {
          type: 'object',
          properties: {foo: {type: 'string'}},
        },
      },
      async () => 'ok'
    );

    const SECRET = 'REDACT_ME';
    const response = await registry.execute('test_tool', {foo: 123, secret: SECRET});

    expect(response.result).toContain('foo');
    expect(response.result).toContain('string');
    expect(response.result).not.toContain('123');
    expect(response.result).not.toContain(SECRET);
  });

  it('asserts register throws at registration time for an uncompilable schema, and that the thrown message names the tool', async () => {
    const registry = new ToolRegistry();
    const badDefinition = {
      name: 'broken_tool',
      description: 'Broken',
      inputSchema: {type: 'invalid_type'},
    };

    expect(() => registry.register(badDefinition as any, async () => 'ok')).toThrow(/broken_tool/);
  });

  it('asserts a function-valued tool definition whose returned schema differs between calls is validated against the schema current at that call', async () => {
    const registry = new ToolRegistry();
    let requiredProp = 'foo';
    registry.register(
      () => ({
        name: 'dynamic_tool',
        description: 'A dynamic tool',
        inputSchema: {
          type: 'object',
          properties: {[requiredProp]: {type: 'string'}},
          required: [requiredProp],
        },
      }),
      async () => 'ok'
    );

    // First call: foo is required
    const res1 = await registry.execute('dynamic_tool', {foo: 'bar'});
    expect(res1.result).toBe('ok');
    const res2 = await registry.execute('dynamic_tool', {baz: 'qux'});
    expect(res2.result).toContain('Property foo is required');

    // Change requirement
    requiredProp = 'baz';
    const res3 = await registry.execute('dynamic_tool', {baz: 'qux'});
    expect(res3.result).toBe('ok');
    const res4 = await registry.execute('dynamic_tool', {foo: 'bar'});
    expect(res4.result).toContain('Property baz is required');
  });

  it('asserts a static tool schema is compiled once across ten execute calls', async () => {
    const registry = new ToolRegistry();
    let calls = 0;
    registry.register(
      {
        name: 'static_tool',
        description: 'Static',
        inputSchema: {type: 'object', properties: {a: {type: 'string'}}},
      },
      async () => {
        calls++;
        return 'ok';
      }
    );

    for (let i = 0; i < 10; i++) {
      await registry.execute('static_tool', {a: 'val'});
    }
    expect(calls).toBe(10);
  });

  it('execute still throws Unknown tool: <name> for an unregistered name', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('missing', {})).rejects.toThrow(/Unknown tool: missing/);
  });

  it('asserts a rejected payload containing an identifying field produces no log line containing that fields value', async () => {
    // This test is harder to verify without spying on logger, but we can verify the result.
    // The requirement also mentions log lines.
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'test_tool',
        description: 'A test tool',
        inputSchema: {
          type: 'object',
          properties: {foo: {type: 'string'}},
        },
      },
      async () => 'ok'
    );

    const SECRET = 'MY_PRIVATE_KEY';
    const response = await registry.execute('test_tool', {foo: 123, secret: SECRET});

    expect(response.result).not.toContain(SECRET);
  });
});

