  it('returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls++;
        return 'Sunny';
      }
    );

    const capturedParams: SendMessageParams[] = [];
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        capturedParams.push(JSON.parse(JSON.stringify(params)));
        const round = capturedParams.length;
        if (round === 1) {
          yield {type: 'tool_use', toolCall: {id: 'call_1', name: 'weather', input: {}}};
          yield STOP_FOR_TOOL;
        } else if (round === 2) {
          yield {type: 'tool_use', toolCall: {id: 'call_2', name: 'weather', input: {location: 'London'}}};
          yield STOP_FOR_TOOL;
        } else {
          yield {type: 'text', text: 'It is sunny.'};
          yield STOP_DONE;
        }
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);
    const session = createSession('ask');
    const result = await orchestrator.processMessage(session);

    expect(result).toBe('It is sunny.');
    expect(executorCalls).toBe(1);

    // Verify round 2 received the rejection from round 1
    const round2Params = capturedParams[1];
    const lastMessage = round2Params.messages[round2Params.messages.length - 1];
    expect(lastMessage.role).toBe('user');
    const content = Array.isArray(lastMessage.content) ? lastMessage.content[0] : lastMessage.content;
    expect(content).toMatchObject({
      type: 'tool_result',
      content: expect.stringMatching(/location.*required/i),
    });

    // Verify round 3 received the successful result from round 2
    const round3Params = capturedParams[2];
    const lastResult = round3Params.messages[round3Params.messages.length - 1];
    expect(lastResult.role).toBe('user');
    const lastContent = Array.isArray(lastResult.content) ? lastResult.content[0] : lastResult.content;
    expect(lastContent).toMatchObject({
      type: 'tool_result',
      content: 'Sunny',
    });
  });
});

